src = io.open(PATH, encoding="utf-8").read()

# sanity: keys must not already exist
for k in new_notes:
    assert f'"{k}": {{' not in src, f"already exists: {k}"
assert src.rstrip().endswith("};")

entries = ",\n".join(
    "  " + json.dumps(k, ensure_ascii=False) + ": " + json.dumps(v, ensure_ascii=False, indent=4).replace("\n", "\n  ")
    for k, v in new_notes.items()
)

idx = src.rstrip().rfind("\n};")
out = src[:idx] + ",\n" + entries + "\n};\n"
io.open(PATH, "w", encoding="utf-8").write(out)
print("Inserted", len(new_notes), "notes. New length:", len(out))
